import{_ as s,H as n,f as a,i as e}from"./chunks/framework.CKQqA5tu.js";const u=JSON.parse('{"title":"技术架构与目录结构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),l={name:"guide/architecture.md"};function p(i,t,r,d,o,c){return n(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="技术架构与目录结构" tabindex="-1">技术架构与目录结构 <a class="header-anchor" href="#技术架构与目录结构" aria-label="Permalink to &quot;技术架构与目录结构&quot;">​</a></h1><p><code>unibestX</code> 基于最新的前端构建工具和 uni-app 原生渲染技术，旨在提供极致的性能和开发体验。</p><h2 id="🛠️-核心技术栈" tabindex="-1">🛠️ 核心技术栈 <a class="header-anchor" href="#🛠️-核心技术栈" aria-label="Permalink to &quot;🛠️ 核心技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">类别</th><th style="text-align:left;">技术</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>框架</strong></td><td style="text-align:left;">uni-app X</td><td style="text-align:left;">下一代 uni-app，基于原生渲染，彻底告别 Webview 的性能瓶颈</td></tr><tr><td style="text-align:left;"><strong>语言</strong></td><td style="text-align:left;">UTS</td><td style="text-align:left;">uni-app Type Script，编译期直接转换为原生 Kotlin(Android) 和 Swift(iOS)</td></tr><tr><td style="text-align:left;"><strong>前端框架</strong></td><td style="text-align:left;">Vue 3</td><td style="text-align:left;">采用 Composition API 编写 UI 逻辑</td></tr><tr><td style="text-align:left;"><strong>构建工具</strong></td><td style="text-align:left;">Vite 5</td><td style="text-align:left;">提供极速的本地开发启动与热更新体验</td></tr><tr><td style="text-align:left;"><strong>CSS 引擎</strong></td><td style="text-align:left;">UnoCSS</td><td style="text-align:left;">按需生成的原子化 CSS，轻量且高效</td></tr><tr><td style="text-align:left;"><strong>UI 组件库</strong></td><td style="text-align:left;">uview-ultra</td><td style="text-align:left;">专为 uni-app X 深度重构的组件库，修复了原生 <code>gap</code>/<code>grid</code> 等布局限制</td></tr><tr><td style="text-align:left;"><strong>分页组件</strong></td><td style="text-align:left;">z-paging-x</td><td style="text-align:left;">提供强大的下拉刷新与分页列表加载体验</td></tr><tr><td style="text-align:left;"><strong>状态管理</strong></td><td style="text-align:left;">x-pinia-s</td><td style="text-align:left;">兼容 uni-app X 的 Pinia 方案</td></tr><tr><td style="text-align:left;"><strong>HTTP 请求</strong></td><td style="text-align:left;">lime-request</td><td style="text-align:left;">uni-app X 兼容的现代化请求库</td></tr><tr><td style="text-align:left;"><strong>国际化</strong></td><td style="text-align:left;">lime-i18n</td><td style="text-align:left;">兼容 vue-i18n 生态的多语言方案</td></tr><tr><td style="text-align:left;"><strong>图表库</strong></td><td style="text-align:left;">e-chart</td><td style="text-align:left;">ECharts 在 uni-app X 中的适配实现</td></tr></tbody></table><h2 id="📁-项目目录结构" tabindex="-1">📁 项目目录结构 <a class="header-anchor" href="#📁-项目目录结构" aria-label="Permalink to &quot;📁 项目目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unibestX/</span></span>
<span class="line"><span>├── plugins/                  # Vite 构建插件（自定义布局插件、根组件注入插件）</span></span>
<span class="line"><span>│   ├── uni-layouts-plugin.ts #   自动布局插件（仿 vite-plugin-uni-layouts）</span></span>
<span class="line"><span>│   └── root-plugin.ts        #   自动包裹 App.ku.uvue 根组件插件</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── api/                  # 业务模块 API 请求函数（foo.uts, user.uts, auth.uts 等）</span></span>
<span class="line"><span>│   ├── assets/               # 静态资源（图标、图片）</span></span>
<span class="line"><span>│   ├── components/           # 公共业务组件（NavBar 自定义通用导航栏）</span></span>
<span class="line"><span>│   ├── http/                 # HTTP 客户端封装（基于 lime-request，拦截器与错误处理）</span></span>
<span class="line"><span>│   ├── i18n/                 # 国际化多语言配置（zh-Hans / en 语言包）</span></span>
<span class="line"><span>│   ├── layouts/              # 页面布局模板（如 default.uvue）</span></span>
<span class="line"><span>│   ├── pages/                # 主应用页面（首页、基础组件展示、原生能力展示、AI助手、个人中心）</span></span>
<span class="line"><span>│   ├── router/               # 全局路由拦截器与登录白名单策略</span></span>
<span class="line"><span>│   ├── store/                # Pinia 状态管理与持久化（app, token, user）</span></span>
<span class="line"><span>│   ├── style/                # 全局样式（UnoCSS / SCSS）</span></span>
<span class="line"><span>│   ├── sub/                  # 应用分包页面（auth, paging, test, uiTest, uview-ultra 等）</span></span>
<span class="line"><span>│   ├── tabbar/               # 自定义 TabBar 组件与状态配置</span></span>
<span class="line"><span>│   ├── types/                # 全局类型定义</span></span>
<span class="line"><span>│   └── utils/                # 全局工具函数（toast, systemInfo, env, backPress 等）</span></span>
<span class="line"><span>├── uni_modules/              # uni-app 扩展插件模块</span></span>
<span class="line"><span>│   ├── unix-crypto/          #   全端跨平台加密解密与安全工具库</span></span>
<span class="line"><span>│   ├── uview-ultra/          #   uni-app X 深度定制 UI 组件库</span></span>
<span class="line"><span>│   ├── z-paging-x/           #   uni-app X 深度定制分页列表组件</span></span>
<span class="line"><span>│   ├── iRainna-lodash/       #   UTS 版 Lodash 工具库</span></span>
<span class="line"><span>│   ├── lime-request/         #   HTTP 请求库</span></span>
<span class="line"><span>│   ├── lime-signature/       #   手写签名板组件</span></span>
<span class="line"><span>│   └── e-chart/              #   ECharts 图表适配组件</span></span>
<span class="line"><span>├── js_sdk/                   # JS / UTS SDK 资源（UnoCSS 解析引擎等）</span></span>
<span class="line"><span>├── docs/                     # VitePress 文档源码</span></span>
<span class="line"><span>├── App.ku.uvue               # 全局根包裹组件（动态主题注入、全局 Toast 容器）</span></span>
<span class="line"><span>├── main.uts                  # 应用的入口文件</span></span>
<span class="line"><span>├── pages.json                # 页面路由表、分包与构建配置</span></span>
<span class="line"><span>├── manifest.json             # 应用配置清单（多端 AppID、权限等）</span></span>
<span class="line"><span>├── vite.config.ts            # Vite 构建配置（UnoCSS 规则、插件与别名）</span></span>
<span class="line"><span>├── uni.scss                  # 全局 SCSS 变量与主题注入</span></span>
<span class="line"><span>└── tsconfig.json             # TypeScript / UTS 编译配置</span></span></code></pre></div>`,6)])])}const f=s(l,[["render",p]]);export{u as __pageData,f as default};
